Layout.Stylesheet:
body { margin: 0; font-size: 9pt; }
div { margin: 5pt; padding: 5pt; border-width: 2pt; border-color: black; }
.none { border-style: none; }
.solid { border-style: solid; }
.dashed { border-style: dashed; }
.dotted { border-style: dotted; }
.double { border-style: double; border-width: 3pt; }
.groove { border-style: groove; border-width: 3pt; }
.ridge { border-style: ridge; border-width: 3pt; }
.inset { border-style: inset; border-width: 3pt; }
.outset { border-style: outset; border-width: 3pt; }
